# -*- coding: utf-8 -*-
"""Deutschland / Klasse 8（Biologie, Chemie, Physik）"""
from de_sci import H, nq, num


def f_dichte(R):
    k = R.choice(["rho", "rho", "m", "V", "schwimmt"])
    if k == "rho":
        m, V = R.choice([(540, 200), (78, 10), (113, 10), (60, 75), (450, 500), (267, 30), (96, 120), (1930, 100), (34, 40), (158, 20)])
        return nq("Ein Körper hat die Masse %s g und das Volumen %s cm³. Wie groß ist seine Dichte?" % (num(m), num(V)), m / V,
                  [V / m, m * V / 1000, m - V], "g/cm³", "ρ = m : V = %s g : %s cm³ = %s g/cm³." % (num(m), num(V), num(m / V)))
    if k == "m":
        rho, V = R.choice([(0.8, 250), (1.2, 50), (0.9, 300), (13.6, 10), (2.5, 40), (7.9, 30), (1.03, 1000), (0.7, 600)])
        return nq("Ein Stoff hat die Dichte %s g/cm³. Welche Masse haben %s cm³ davon?" % (num(rho), num(V)), rho * V,
                  [V / rho, rho + V, rho * V * 10], "g", "m = ρ · V = %s g/cm³ · %s cm³ = %s g." % (num(rho), num(V), num(rho * V)))
    if k == "V":
        rho, m = R.choice([(2.7, 81), (8.9, 178), (11.3, 226), (2.7, 135), (19.3, 386), (7.9, 395)])
        return nq("Ein Metallstück hat die Masse %s g und die Dichte %s g/cm³. Wie groß ist sein Volumen?" % (num(m), num(rho)), m / rho,
                  [m * rho, m - rho, m / rho * 10], "cm³", "V = m : ρ = %s g : %s g/cm³ = %s cm³." % (num(m), num(rho), num(m / rho)))
    m, V = R.choice([(30, 50), (80, 100), (120, 100), (45, 30), (90, 200), (250, 200), (12, 20), (64, 40)])
    sw = m / V < 1
    return nq("Ein Körper mit %s g und %s cm³ wird ins Wasser gelegt. Wie groß ist seine Dichte?" % (num(m), num(V)), m / V,
              [V / m, m - V if m > V else V - m, m * V / 100], "g/cm³",
              "ρ = %s g : %s cm³ = %s g/cm³. Das ist %s als 1 g/cm³, also %s er." % (num(m), num(V), num(m / V), "weniger" if sw else "mehr", "schwimmt" if sw else "sinkt"))


def f_druck(R):
    k = R.choice(["p", "p", "F", "wasser", "auftrieb"])
    if k == "p":
        F, A = R.choice([(600, 0.03), (500, 0.05), (800, 0.2), (1000, 0.5), (200, 0.01), (50, 0.0025), (12000, 0.4), (700, 0.07)])
        return nq("Eine Kraft von %s N wirkt auf eine Fläche von %s m². Wie groß ist der Druck?" % (num(F), num(A)), F / A,
                  [F * A, A / F * 10 ** 6, F / A / 100], "Pa", "p = F : A = %s N : %s m² = %s Pa." % (num(F), num(A), num(F / A)))
    if k == "F":
        p, A = R.choice([(200000, 0.002), (100000, 0.5), (2000, 0.3), (50000, 0.01), (300000, 0.0015)])
        return nq("In einem Zylinder herrscht der Druck %s Pa. Welche Kraft wirkt auf einen Kolben mit %s m²?" % (num(p), num(A)), p * A,
                  [p / A, A / p * 10 ** 6, p * A * 10], "N", "F = p · A = %s Pa · %s m² = %s N." % (num(p), num(A), num(p * A)))
    if k == "wasser":
        h = R.choice([2, 5, 10, 20, 30, 50, 100, 4])
        return nq("Welcher Schweredruck herrscht in %d m Wassertiefe ungefähr? (Pro 10 m nimmt er um 1 bar zu.)" % h, h / 10,
                  [h, h / 100, h * 10], "bar", "Pro 10 m kommt 1 bar dazu: %d m : 10 m · 1 bar = %s bar (ohne Luftdruck)." % (h, num(h / 10)))
    V = R.choice([100, 200, 250, 500, 1000, 2000, 50, 400])
    return nq("Ein Körper mit %s cm³ taucht vollständig in Wasser. Wie groß ist die Auftriebskraft? (1 cm³ Wasser wiegt etwa 0,01 N)" % num(V), V * 0.01,
              [V * 0.1, V, V * 0.001], "N", "Der Auftrieb ist so groß wie die Gewichtskraft des verdrängten Wassers: %s cm³ · 0,01 N = %s N." % (num(V), num(V * 0.01)))


def f_energie(R):
    k = R.choice(["W", "W", "P", "Epot", "t"])
    if k == "W":
        F, s = R.choice([(50, 4), (200, 3), (120, 10), (35, 20), (600, 2), (80, 15), (250, 6)])
        return nq("Ein Schrank wird mit %s N über %s m geschoben. Welche Arbeit wird verrichtet?" % (num(F), num(s)), F * s,
                  [F / s, F + s, F * s / 10], "J", "W = F · s = %s N · %s m = %s J." % (num(F), num(s), num(F * s)))
    if k == "P":
        W, t = R.choice([(1200, 4), (3000, 10), (600, 5), (9000, 30), (2400, 8), (500, 2), (15000, 60)])
        return nq("Eine Arbeit von %s J wird in %s s verrichtet. Wie groß ist die Leistung?" % (num(W), num(t)), W / t,
                  [W * t, t / W * 1000, W - t], "W", "P = W : t = %s J : %s s = %s W." % (num(W), num(t), num(W / t)))
    if k == "Epot":
        m, h = R.choice([(50, 3), (2, 10), (60, 12), (5, 4), (40, 2), (0.5, 20), (70, 8)])
        return nq("Eine Masse von %s kg wird %s m hoch gehoben. Wie groß ist die Lageenergie? (g ≈ 10 N/kg)" % (num(m), num(h)), m * h * 10,
                  [m * h, m * 10 + h, m * h * 100], "J", "E = m · g · h = %s kg · 10 N/kg · %s m = %s J." % (num(m), num(h), num(m * h * 10)))
    W, P = R.choice([(6000, 200), (1800, 60), (12000, 400), (2000, 50), (9000, 300)])
    return nq("Ein Motor mit %s W soll eine Arbeit von %s J verrichten. Wie lange braucht er?" % (num(P), num(W)), W / P,
              [W * P / 1000, P / W * 100, W - P], "s", "t = W : P = %s J : %s W = %s s." % (num(W), num(P), num(W / P)))


def f_hebel(R):
    k = R.choice(["F", "F", "a", "rolle"])
    if k == "F":
        F1, a1, a2 = R.choice([(100, 0.2, 0.8), (300, 0.5, 1.5), (60, 0.3, 0.9), (500, 0.1, 1), (40, 0.25, 1), (200, 0.4, 1.6), (90, 0.6, 1.8), (150, 0.2, 0.6), (240, 0.3, 1.2), (800, 0.25, 2), (120, 0.5, 2)])
        F2 = F1 * a1 / a2
        return nq("Hebelgesetz: Eine Last von %s N hängt %s m vom Drehpunkt. Welche Kraft braucht man im Abstand %s m?" % (num(F1), num(a1), num(a2)), F2,
                  [F1 * a2 / a1, F1, F1 * a1 * a2], "N", "F₁ · a₁ = F₂ · a₂, also F₂ = %s N · %s m : %s m = %s N." % (num(F1), num(a1), num(a2), num(F2)))
    if k == "a":
        F1, a1, F2 = R.choice([(200, 0.5, 50), (600, 0.2, 100), (120, 0.4, 30), (80, 1, 20), (450, 0.2, 90)])
        return nq("Auf einer Wippe sitzt ein Kind (%s N) %s m vom Drehpunkt. Wo muss eine Kraft von %s N angreifen, damit Gleichgewicht herrscht?" % (num(F1), num(a1), num(F2)), F1 * a1 / F2,
                  [F2 * a1 / F1, F1 / F2, a1], "m", "a₂ = F₁ · a₁ : F₂ = %s N · %s m : %s N = %s m." % (num(F1), num(a1), num(F2), num(F1 * a1 / F2)))
    F, n = R.choice([(400, 2), (600, 3), (800, 4), (300, 2), (900, 3), (1200, 4), (1500, 6), (500, 2), (1000, 4), (720, 6), (240, 3), (2000, 5)])
    return nq("Ein Flaschenzug hat %d tragende Seilstücke. Welche Kraft braucht man für eine Last von %s N?" % (n, num(F)), F / n,
              [F * n, F, F / n / 2], "N", "Die Last verteilt sich auf %d Seilstücke: %s N : %d = %s N. Dafür ist der Zugweg %d-mal so lang." % (n, num(F), n, num(F / n), n))


